let activeScene=0,selected=null;const $=id=>document.getElementById(id);function e(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function render(){const s=scenes[activeScene];$('sceneTitle').textContent=s.title;$('sceneSub').textContent=s.sub;$('pageBadge').textContent=s.page;$('diagramImg').src=s.image;$('diagramImg').alt='رسم '+s.title+' من الدليل؛ اضغط الأرقام لعرض أسماء القطع';$('markers').innerHTML=s.parts.map(p=>`<button class="marker ${selected===p[0]?'selected':''}" style="left:${p[3]}%;top:${p[4]}%" data-number="${p[0]}" title="${e(p[1])}" aria-label="القطعة ${p[0]}: ${e(p[1])}">${p[0]}</button>`).join('');$('markers').querySelectorAll('button').forEach(b=>b.onclick=()=>select(+b.dataset.number));$('partCount').textContent=s.parts.length+' قطعة';renderList();renderDetails()}
function renderList(){let q=$('search').value.trim().toLowerCase(),items=scenes[activeScene].parts.filter(p=>p[1].toLowerCase().includes(q)||p[2].toLowerCase().includes(q)||String(p[0]).includes(q));$('partsList').innerHTML=items.length?items.map(p=>`<button class="part ${selected===p[0]?'active':''}" data-number="${p[0]}"><span>${p[0]}</span><div><b>${e(p[1])}</b><small>${e(p[2])}</small></div></button>`).join(''):'<div class="empty-search">لم نجد قطعة بهذا الاسم أو الرقم في الرسم الحالي.</div>';$('partsList').querySelectorAll('button').forEach(b=>b.onclick=()=>{select(+b.dataset.number);$('diagram').scrollIntoView({behavior:'smooth',block:'start'})})}
function renderDetails(){const s=scenes[activeScene],p=s.parts.find(x=>x[0]===selected);$('infoNum').textContent=p?'# '+p[0]:'—';$('details').innerHTML=p?`<div class="info-selected"><div class="part-index">${p[0]}</div><h3>${e(p[1])}</h3><div class="english">${e(p[2])}</div><div class="detail-label">المصدر</div><div class="detail-value">${e(s.source)}</div><div class="detail-label" style="margin-top:18px">ملاحظة</div><div class="detail-value">الاسم مطابق لمفتاح الرسم في الدليل، والموقع تقريبي على الرسم النموذجي.</div></div>`:'<div class="info-empty"><div class="target">⌾</div><h3>اختر مكوّنًا للبدء</h3><p>اضغط على أحد الأرقام في الرسم أو اختر من القائمة أدناه لعرض اسمه ورقمه.</p></div>'}function select(n){selected=n;render()};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{activeScene=+b.dataset.scene;selected=null;$('search').value='';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));render()});$('search').oninput=renderList;$('resetZoom').onclick=()=>{selected=null;render()};document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>$(b.dataset.target).scrollIntoView({behavior:'smooth'}));render();
